const url = require('url')
const ffmpeg = require('fluent-ffmpeg')
const icy = require('icy')
const fs = require('fs')
const { promisify } = require('util')
// eslint-disable-next-line n/no-deprecated-api
const existsAsync = promisify(fs.exists)
const path = require('path')

const { createStream, sleep } = require('./utils')
const log = require('./logger')

/\*\*
 \* Converting a input audio-stream into another format.
 \* E.g. MP3 into HLS
 \*/
class AudioConverter {
 /\*\*
 \* AudioConverter constructor
 \*
 \* @param {object} config
 \* @param {string} config.sourceStreamUrl - URL of the source stream
 \* @param {string} config.sourceStreamOffset - time in ms to delay the stream to insert ads later than signaled
 \* @param {string} config.adBreakKeyword - If this string is detected in the metadata ad start is considered
 \* @param {string} config.adBreakDurationRegex - Regex to parse the duration of the ad-break
 \* @param {string} config.authHeader - Authorization header to request the source stream
 \* @param {string} config.icyMetadata - 1 to enable metadata/ 0 to diable metadata (Default: 0)
 \* @param {string} config.icyMetaInt - Interval in bits between the mp3-stream metadata blocks (Default: 16000)
 \*/
 constructor ({
 sourceStreamUrl,
 sourceStreamOffset = 0,
 adBreakKeyword = 'WERBUNG',
 adBreakDurationRegex,
 authHeader,
 icyMetadata = 1,
 icyMetaInt = 16000,
 interval,
 hlsSegmentLength = 5
 }) {
 this.sourceStreamUrl = sourceStreamUrl
 this.sourceStreamOffset = Number(sourceStreamOffset)
 this.adBreakKeyword = adBreakKeyword
 this.adBreakDurationRegex = adBreakDurationRegex
 this.authHeader = authHeader
 this.icyMetadata = icyMetadata
 this.icyMetaInt = icyMetaInt
 this.interval = Number(interval)
 this.hlsSegmentLength = Number(hlsSegmentLength)

 this.channels = [
 createStream(),
 createStream()
 ]
 this.streamRunning = 0
 this.ffmpegInstances = []
 this.adStartMediaSequenceNumber = 0
 this.durationOfNextAdBreak = null
 this.insideAdBreak = false
 this.initialState = true
 this.bootWaitCycles = 0
 }

 /\*\*
 \* Initialisation of convertion process
 \*/
 async init () {
 try {
 this.startScan(0)
 await this.waitUntilConverterIsRunning()
 } catch (e) {
 e.message = 'Cannot initalize scanning process: ' + e.message
 throw e
 }
 }

 /\*\*
 \* Wait until the first HLS files arrive as convertion result
 \* This is the prerequisite to start the web-server
 \*/
 async waitUntilConverterIsRunning () {
 try {
 const master = await existsAsync(path.join(\_\_dirname, '../out/master.m3u8'))
 const playlist = await existsAsync(path.join(\_\_dirname, '../out/playlist.m3u8'))
 if (!master || !playlist) throw new Error('No playlist or master manifest available')
 } catch (e) {
 if (this.bootWaitCycles > 60) throw new Error('Cannot start converter. After 60 Seconds still no output is generated: ' + e.message)
 this.bootWaitCycles++
 log.debug('Transcoding process not yet running. Retry in 1 sec. (boot wait cycle: ' + this.bootWaitCycles + ')')
 await sleep(1000)
 await this.waitUntilConverterIsRunning()
 }
 }

 /\*\*
 \* Constantly check if the source stream plays content or ads
 \*/
 startScan (channel = 0) {
 log.info('Start Scanning Source Stream: ' + this.sourceStreamUrl)

 try {
 // eslint-disable-next-line n/no-deprecated-api
 const requestOptions = url.parse(this.sourceStreamUrl)
 requestOptions.headers = {
 'Icy-MetaData': this.icyMetadata && String(this.icyMetadata),
 'Icy-MetaInt': this.icyMetaInt && String(this.icyMetaInt)
 }
 if (this.authHeader) requestOptions.headers.Authorization = this.authHeader

 icy.get(requestOptions, this.sourceStreamProcessing.bind(this))
 } catch (e) {
 e.message = 'Cannot scan source stream: ' + e.message
 throw e
 }
 }

 /\*\*
 \* Process the source stream response
 \*
 \* @param {object} response
 \*/
 sourceStreamProcessing (response) {
 log.info('Start stream')
 log.debug('Source Stream Response: \n Status: ' + response.res.statusCode + ' ' + response.res.statusMessage + '\n Headers: ' + JSON.stringify(response.res.headers) + '\n ')

 if (this.interval) {
 // If we automatically insert every X seconds we do not need to parse the metadata
 response.on('metadata', () => { })
 setInterval(() => {
 if (!this.insideAdBreak) {
 this.durationOfNextAdBreak = this.interval
 this.insideAdBreak = true
 } else {
 this.insideAdBreak = false
 }
 this.switchStream()
 }, this.interval \* 1000)
 } else response.on('metadata', this.parseMetadata.bind(this))

 response.on('data', this.processData.bind(this))
 response.on('error', this.handleError.bind(this))

 this.initFfmpeg.bind(this)()
 }

 /\*\*
 \* Parse the stream metadata
 \*
 \* @param {Buffer} metadata
 \*/
 parseMetadata (metadata) {
 try {
 const parsed = icy.parse(metadata)
 console.log(parsed)
 const streamName = parsed.StreamTitle
 console.log(streamName)
 log.info('Got (initial or changed) Source Stream Metadata: ' + JSON.stringify(parsed))

 if (streamName.includes(this.adBreakKeyword)) {
 log.info('Detected Ad-Marker')
 const duration = this.parseDuration(streamName)
 log.info('Detected Ad-Break Duration: ' + duration)
 this.durationOfNextAdBreak = duration
 this.insideAdBreak = true
 this.switchStream()
 } else {
 this.insideAdBreak = false
 if (this.initialState) this.initialState = false
 else this.switchStream()
 }
 } catch (e) {
 e.message = 'Cannot parse metadata: ' + e.message
 console.error(e)
 }
 }

 /\*\*
 \* Parse the ad-break duration from the source stream metadata
 \*
 \* @param {string} input - Metadata String to parse
 \* @returns {number} duration - duration in seconds
 \*/
 parseDuration (input) {
 try {
 const regexString = this.adBreakDurationRegex
 const regex = new RegExp(regexString || /(\d\*(?:\.\d+)?)$/, 'g')
 const parsingResult = regex.exec(input)
 const duration = Number(parsingResult && parsingResult[0])
 if (!duration) throw new Error('Cannot extract duration from input. Please check your regex. (Input "' + input + '", "' + regex + '", Parsing Result: "' + JSON.stringify(parsingResult) + '")')
 return duration
 } catch (e) {
 e.message = 'Cannot parse duration: ' + e.message
 throw e
 }
 }

 /\*\*
 \* Method to process stream data - in this case forwarding to the one or th other duplex stream
 \*
 \* @param {Buffer} chunk
 \*/
 processData (chunk) {
 this.channels[this.streamRunning].push(chunk)
 }

 /\*\*
 \* Method to handle source stream parsing issues
 \*
 \* @param {object} error - JS error object
 \*/
 handleError (error) {
 log.error(error)
 }

 /\*\*
 \* Initialize the convertion FFMPEG process
 \*/
 initFfmpeg () {
 this.ffmpegInstances[0] = this.convertMp3ToHls({ stream: this.channels[0], channel: 0 })
 this.ffmpegInstances[0].run()
 }

 /\*\*
 \* Switch to another duplex channel to start another ffmpeg instance
 \*
 \* @description
 \*
 \* This switch leads to FFMPEG cropping of the hls data at the current position.
 \* That way it is possible to crop the HLS segments at the exact position where ads are inserted.
 \* The next instance of FFMPEG will pick up the state and insert a DISCONTINITY tag.
 \* We can use the tag later in the processing to insert SCTE-35 Marker.
 \*/
 async switchStream () {
 try {
 await sleep(this.sourceStreamOffset)

 log.info('End Stream: ' + this.streamRunning)
 // Stop the current stream
 this.channels[this.streamRunning].push(null)

 // Switch to the other stream
 this.streamRunning = (this.streamRunning + 1) % 2
 this.channels[this.streamRunning] = createStream()

 // Initialize a new ffmpeg instance for the new stream
 this.ffmpegInstances[this.streamRunning] = this.convertMp3ToHls({ stream: this.channels[this.streamRunning], channel: this.streamRunning })
 this.ffmpegInstances[this.streamRunning].run()
 this.adStartMediaSequenceNumber++

 log.info('Stream running: ' + this.streamRunning)
 } catch (e) {
 e.message = 'Cannot switch streams: ' + e.message
 log.error(e)
 }
 }

 /\*\*
 \* Start an FFMPEG process to convert Mp3 to HLS.
 \*
 \* @param {Duplex} stream - stream to use for ffmpeg processing
 \* @param {number} channel - currently used channel
 \*/
 convertMp3ToHls ({ stream, channel }) {
 const instance = ffmpeg(stream)
 .noVideo()
 .audioCodec('aac')
 .audioBitrate('256k')
 .format('hls')
 .outputOptions([
 '-hls\_time ' + this.hlsSegmentLength, // Segment length
 '-hls\_segment\_type mpegts',
 '-hls\_segment\_filename out/file-%01d.ts',
 '-hls\_list\_size 30', // Window
 '-hls\_flags append\_list+omit\_endlist+delete\_segments',
 '-master\_pl\_name master.m3u8'
 ])
 .output('out/playlist.m3u8')
 .on('end', function () {
 log.debug('FFMPEG: Done processing input stream')
 })
 .on('error', function (err) {
 log.error('FFMPEG: An error happened on channel[' + channel + ']: ' + err.message)
 })
 .on('progress', function (str) {
 log.debug('FFMPEG: Transcoding Channel[' + channel + ']: Progress: ' + JSON.stringify(str.timemark))
 })

 return instance
 }
}

module.exports = AudioConverter
